from collections import deque

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if g[r][c] == 8 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and g[ny][nx] != 8 and (ny,nx) not in seen:
                        seen.add((ny,nx)); q.append((ny,nx))
            r0, r1 = min(y for y,x in cells), max(y for y,x in cells)
            c0, c1 = min(x for y,x in cells), max(x for y,x in cells)
            colors = [(y,x) for y,x in cells if g[y][x] not in (0,8)]
            if not colors:
                continue
            pr0, pr1 = min(y for y,x in colors), max(y for y,x in colors)
            pc0, pc1 = min(x for y,x in colors), max(x for y,x in colors)
            ph, pw = pr1-pr0+1, pc1-pc0+1
            pattern = [[g[pr0+i][pc0+j] for j in range(pw)] for i in range(ph)]
            for y in range(r0, r1+1):
                for x in range(c0, c1+1):
                    g[y][x] = pattern[(y-pr0) % ph][(x-pc0) % pw]
    return g

